function modal(title,description,body,footer='',wide=false){
  const d=$('#modal');d.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${description?`<p>${description}</p>`:''}</div>${ib('close','Đóng hộp thoại','close-modal')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;
  d.style.width=wide?'min(700px, calc(100% - 32px))':'min(540px, calc(100% - 32px))';if(!d.open)d.showModal();
}
function closeModal(){$('#modal').close();}
function guide(){
  const screens=[['overview','Tổng quan','grid'],['projects','Danh sách dự án','folder'],['project/p1','Chi tiết dự án','folder'],['chat/c1','Hội thoại AI','chat'],['chat/new','Hội thoại mới','plus'],['library','Kho hội thoại','library'],['integrations','Nguồn AI & tài khoản','plug'],['team','Nhân viên','people'],['usage','Chi phí & ngân sách','chart'],['imports','Nhập lịch sử','upload'],['audit','Nhật ký hoạt động','activity'],['settings','Cài đặt & quyền','settings'],['login','Đăng nhập','lock']];
  modal('Khám phá prototype','Giao diện chi tiết · Dữ liệu mẫu · Không gọi API thật',`<div class="screen-map">${screens.filter(([r])=>S.role==='owner'||!['integrations','team','imports','audit'].includes(r)).map(([path,label,ic])=>`<button data-action="navigate" data-path="${path}">${icon(ic)}${label}</button>`).join('')}</div><div class="divider"></div><h3>Xem các trạng thái giao diện</h3><p class="small muted mt12">Chọn một trạng thái để kiểm tra cách hệ thống phản hồi.</p><div class="row wrap mt12">${[['normal','Bình thường'],['empty','Dữ liệu trống'],['loading','Đang tải'],['error','Lỗi kết nối'],['budget','Hết ngân sách'],['readonly','Chỉ xem']].map(([id,label])=>btn(label,'demo-state','','',`data-id="${id}"`)).join('')}</div><div class="info-banner">${icon('info')}Tên, email, số tiền và phản hồi đều là dữ liệu minh họa. Thao tác chỉ thay đổi giao diện trong phiên xem; tải lại trang để khôi phục.</div>`,btn('Tiếp tục khám phá','close-modal','','primary'),true);
}
function newProject(){modal('Tạo dự án mới','Một không gian riêng để giữ công việc theo đúng mục tiêu.',`<form id="new-project-form"><div class="field"><label for="project-name">Tên dự án <span class="red">*</span></label><input class="input" id="project-name" placeholder="Ví dụ: Nghiên cứu sản phẩm mới" maxlength="70" required><span class="hint">Tên rõ ràng giúp đội ngũ tìm lại công việc dễ hơn.</span></div><div class="field"><label for="project-description">Mô tả</label><textarea class="input" id="project-description" placeholder="Mục tiêu và phạm vi của dự án..." maxlength="250"></textarea></div><div class="field"><label for="project-category">Phân loại</label><select class="input" id="project-category"><option>Nghiên cứu</option>Marketing</option>Thương hiệu</option>Vận hành</option>Sản phẩm</option></select></div>${notice('Dự án công việc — chủ doanh nghiệp có quyền xem nội dung. Bạn có thể chia sẻ với thành viên sau khi tạo.')}<p class="tiny muted">Đây là thao tác mô phỏng, không tạo dữ liệu trên máy chủ.</p></form>`,btn('Hủy','close-modal')+btn('Tạo dự án mẫu','create-project','plus','primary'));}
function shareProject(id){const p=project(id),isManager=p.owner===me().id;modal(isManager?'Chia sẻ dự án':'Quyền truy cập dự án',p.name,`${notice('Chủ doanh nghiệp luôn có quyền xem dự án công việc. Quyền đóng góp được quản lý riêng.')}${[p.owner,...p.members].map(uid=>`<div class="file-row">${avatar(uid)}<div class="file-info"><strong>${person(uid).name}</strong><p>${person(uid).email}</p></div>${uid===p.owner?pill('Chủ dự án','green'):isManager?`<select class="select" data-member-right="${uid}" aria-label="Quyền của ${person(uid).name}"><option ${!p.write.includes(uid)?'selected':''}>Chỉ xem</option><option ${p.write.includes(uid)?'selected':''}>Đóng góp</option></select>`:pill(p.write.includes(uid)?'Đóng góp':'Chỉ xem')}</div>`).join('')}${isManager?`<div class="field mt24"><label for="share-member">Thêm thành viên</label><select class="input" id="share-member"><option value="">Chọn thành viên trong công ty</option>${NEX.people.filter(u=>u.id!==p.owner&&!p.members.includes(u.id)).map(u=>`<option value="${u.id}">${u.name}</option>`).join('')}</select></div><p class="tiny muted">Quyền “Chỉ xem” cho phép đọc nội dung. Quyền “Đóng góp” cho phép tiếp tục trao đổi và thêm nội dung.</p>`:'<p class="small muted mt24">Bạn có quyền xem. Việc thay đổi thành viên cần chủ dự án hoặc người được ủy quyền.</p>'}`,btn('Đóng','close-modal')+(isManager?btn('Xem trước chia sẻ','share-save','people','primary',`data-id="${id}"`):''));}
function modelPicker(branch=false,projectId='p1'){modal(branch?'Tiếp tục bằng AI khác':'Chọn nguồn AI',branch?'Hub tạo một nhánh mới và giữ nguyên hội thoại gốc.':'Chọn kết nối được cấp quyền trong không gian làm việc.',`${NEX.providers.map(p=>`<button class="modal-option ${p.id===S.provider?'selected':''}" data-action="${branch?'branch-model':'model-select'}" data-id="${p.id}" data-project="${projectId}" ${p.id==='meta'?'disabled':''}>${symbol(p.id,true)}<span class="grow"><strong>${p.name} · ${p.mode}</strong><p>${p.hint}</p></span>${p.id===S.provider?icon('check'):p.id==='meta'?pill('Chờ xác minh','amber'):icon('chevron')}</button>`).join('')}${branch?notice('Chỉ phần ngữ cảnh được chọn của hội thoại này sẽ được gửi sang nguồn AI mới. Trong prototype, thao tác chỉ mở một màn hình mẫu.'):'<p class="tiny muted mt12">Tên model và hạn mức thật được cấu hình khi kết nối. Các lựa chọn này mô tả trải nghiệm mẫu.</p>'}`,btn('Hủy','close-modal'));}
function connectModal(id='openai'){const p=provider(id);modal('Thiết lập kết nối AI','Chỉ chủ doanh nghiệp quản lý khóa và quyền sử dụng.',`<div class="field"><label for="connect-provider">Nhà cung cấp</label><select class="input" id="connect-provider">${NEX.providers.map(pr=>`<option value="${pr.id}" ${pr.id===id?'selected':''}>${pr.name}</option>`).join('')}</select></div><div class="field"><label for="connection-name">Tên kết nối</label><input class="input" id="connection-name" value="NexMO · ${p.name}"></div><div class="field"><label for="connection-key">API key</label><input class="input mono" id="connection-key" value="•••• •••• •••• DEMO" readonly><span class="hint">Khóa giả chỉ để xem giao diện. Không nhập khóa thật vào prototype.</span></div><div class="field"><label>Quyền sử dụng</label><div class="row wrap">${NEX.people.filter(u=>u.id!=='owner').map(u=>`<label class="check-field"><input type="checkbox" checked>${u.name.split(' ')[0]}</label>`).join('')}</div></div>${notice('Một kết nối chung, ngữ cảnh riêng cho từng hội thoại. Nhân viên không thấy API key.')}`,btn('Hủy','close-modal')+btn('Kiểm tra mẫu','test-connection','plug','primary',`data-id="${id}"`));}
function providerDetail(id){const p=provider(id);if(id==='meta'){modal('Meta AI — trạng thái tích hợp','Chưa xác minh quyền truy cập API.',`<div class="row">${symbol(id,true)}<div><h3>Meta AI Free</h3><p class="small muted">Tài khoản hiện có trong danh mục</p></div></div>${notice('Tài khoản website không tự cấp quyền API. Chưa thể bật chat trực tiếp với Meta trong bản thiết kế này.','amber')}<div class="check-list"><div>${icon('check')}Quản lý thông tin tài khoản</div><div>${icon('check')}Lưu nội dung được nhập thủ công</div><div>${icon('clock')}Kiểm chứng API, model và hạn mức trước tích hợp</div></div>`,btn('Đã hiểu','close-modal','','primary'));return;}modal(`Kết nối ${p.name}`,'NexMO · Kết nối mẫu của công ty',`<div class="row between">${symbol(id,true)}${pill('Kết nối mẫu hoạt động','green dot')}</div><div class="definition"><div class="definition-row"><span>Loại kết nối</span><strong>API tập trung</strong></div><div class="definition-row"><span>Model mẫu</span><strong>${p.mode}</strong></div><div class="definition-row"><span>Quyền sử dụng</span><strong>5 nhân viên + Owner</strong></div><div class="definition-row"><span>Chi phí tháng mẫu</span><strong>${money(p.cost)}</strong></div></div><div class="provider-key">${icon('key')}•••• •••• •••• DEMO</div>${notice('Trạng thái minh họa. Chưa có API key hay kết nối thật trong prototype.')}`,btn('Đóng','close-modal')+btn('Chỉnh cấu hình mẫu','connect','settings','primary',`data-id="${id}"`));}
function employeeModal(id){const p=person(id);modal(p.name,'Quyền sử dụng AI và hạn mức cá nhân',`<div class="row">${avatar(id,'lg')}<div><h3>${p.job}</h3><p class="small muted">${p.email}</p></div></div><div class="divider"></div><h3>Nguồn AI được sử dụng</h3><div class="check-list">${NEX.providers.slice(0,3).map(pr=>`<label class="check-field"><input type="checkbox" checked>${symbol(pr.id)}${pr.name}</label>`).join('')}</div><div class="field mt24"><label for="employee-budget">Hạn mức tháng · USD mẫu</label><input class="input" id="employee-budget" type="number" min="1" value="${p.limit}"><span class="hint">Đã sử dụng ${money(p.cost)}. Đây là số liệu thiết kế, không phải ngân sách đã chốt.</span></div><div class="info-banner">${icon('shield')}Nhân viên chỉ xem dự án của mình và dự án được chia sẻ.</div><div class="row between"><span class="small muted">Trạng thái tài khoản mẫu</span>${btn(p.status==='locked'?'Mở khóa mẫu':'Khóa tài khoản mẫu','lock-employee',p.status==='locked'?'refresh':'lock','danger',`data-id="${id}"`)}</div>`,btn('Đóng','close-modal')+btn('Lưu bản xem trước','employee-save','check','primary',`data-id="${id}"`));}
function budgetModal(){modal('Ngân sách sử dụng AI','Thiết lập giới hạn cho toàn bộ không gian làm việc.',`<div class="field"><label for="company-budget">Ngân sách tháng · USD mẫu</label><input id="company-budget" class="input" type="number" min="1" value="150"><span class="hint">Giá trị chỉ minh họa bố cục; ngân sách thật chưa được chốt.</span></div><div class="form-grid"><div class="field"><label for="warning-one">Cảnh báo lần đầu</label><select id="warning-one" class="input"><option>80% ngân sách</option><option>75% ngân sách</option></select></div><div class="field"><label for="warning-two">Cảnh báo tiếp theo</label><select id="warning-two" class="input"><option>95% ngân sách</option><option>90% ngân sách</option></select></div></div><div class="settings-row"><div><strong>Dừng lượt AI mới khi không đủ ngân sách</strong><p>Vẫn cho phép đọc và xuất hội thoại đã lưu.</p></div><span class="pill green">Luôn bật</span></div>${notice('Chi phí thực tế cần đối soát với nhà cung cấp. Lượt đang chạy và usage báo muộn có thể ảnh hưởng số dư.')}<p class="tiny muted">Prototype không thay đổi billing hoặc phát sinh chi phí.</p>`,btn('Đóng','close-modal')+btn('Xem trạng thái hết hạn mức','demo-state','','soft','data-id="budget"')+btn('Xem trước cấu hình','budget-save','check','primary'));}
function filePreview(id){const names=['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx','Ghi chú dự án.md'];modal(names[Number(id)||0],'Tài liệu mẫu · Không phải tệp được tải lên',`<div class="panel panel-padding" style="background:#fafbf7"><div class="eyebrow">NEXMO · TÀI LIỆU DỰ ÁN</div><h2 class="mt12">Khung nghiên cứu khách hàng</h2><p class="small muted mt12">Nội dung sau minh họa trải nghiệm xem tài liệu ngay trong Hub.</p><div class="divider"></div><h3>Mục tiêu nghiên cứu</h3><p class="small mt12">Hiểu vấn đề khách hàng đang gặp, cách họ giải quyết hiện tại và tiêu chí để cân nhắc một lựa chọn mới.</p><h3 class="mt24">Những câu hỏi cần làm rõ</h3><ul class="small"><li>Vấn đề xuất hiện trong tình huống nào?</li><li>Giải pháp hiện tại còn điểm gì bất tiện?</li><li>Kết quả nào sẽ tạo ra khác biệt?</li></ul><div class="divider"></div><p class="tiny muted">Tài liệu này chỉ dùng để trình bày thiết kế. Không có dữ liệu khách hàng thật.</p></div>`,btn('Đóng','close-modal','','primary'),true);}
function contextModal(id){const p=project(id);modal('Ngữ cảnh hội thoại',p.name,`<h3>Phạm vi được dùng cho lượt trao đổi</h3><div class="check-list"><div>${icon('check')}Tin nhắn trong nhánh hội thoại đang mở</div><div>${icon('check')}Tài liệu được người dùng chọn</div><div>${icon('shield')}Quyền truy cập của dự án được áp dụng</div></div><div class="divider"></div><h3>Tài liệu mẫu</h3>${['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx'].map((n,i)=>`<button class="modal-option" data-action="file-preview" data-id="${i}">${icon('file')}<span class="grow">${n}</span>${icon('eye')}</button>`).join('')}${notice('Dữ liệu dự án khác không tự được gửi kèm, kể cả khi Owner có quyền xem nhiều dự án.')}`,btn('Đóng','close-modal','','primary'));}
function dispatch(a,id,el,e){
  const handled=['guide','close-modal','workspace','search','notifications','navigate','new-project','create-project','share','share-save','quick-chat','project-chat','models','model-select','branch','branch-model','suggest','send','stop','retry','attach','file-preview','context','copy-answer','like','chat-options','export-chat','connect','provider-detail','test-connection','integration-tab','subscription','save-subscription','invite','invite-preview','employee','employee-save','lock-employee','confirm-lock','budget','budget-save','month','export-usage','import-provider','sample-file','import-next','import-back','import-reset','import-help','settings-tab','save-settings','toggle','audit-filter','forgot','forgot-preview','login-role','demo-state'];
  if(!handled.includes(a))return false;e.preventDefault();
  switch(a){
    case 'guide':guide();break;
    case 'close-modal':closeModal();break;
    case 'navigate':closeModal();S.view='normal';go(el.dataset.path);break;
    case 'workspace':modal('NexMO Workspace','Một không gian làm việc chung cho công ty.',`<div class="row">${mark()}<div><h3>Nex AI Hub</h3><p class="small muted">1 chủ doanh nghiệp · 5 nhân viên</p></div></div><div class="check-list"><div>${icon('check')}Nhân viên chỉ đăng nhập Hub</div><div>${icon('check')}Kết nối API do công ty quản lý</div><div>${icon('check')}Dữ liệu được tổ chức theo dự án</div></div>`,btn('Đóng','close-modal','','primary'));break;
    case 'search':modal('Tìm trong không gian làm việc','Chỉ tìm kiếm trong các dự án bạn được xem.',`<form id="global-search-form"><div class="input-icon">${icon('search')}<input class="input" id="global-search" autofocus placeholder="Tìm hội thoại, ý tưởng hoặc dự án..." aria-label="Từ khóa tìm kiếm"></div><div class="mt24 eyebrow">GỢI Ý GẦN ĐÂY</div>${visibleChats().slice(0,3).map(c=>`<button type="button" class="modal-option mt12" data-action="navigate" data-path="chat/${c.id}">${symbol(c.provider)}<span class="grow"><strong>${c.title}</strong><p>${project(c.project).name}</p></span>${icon('arrow')}</button>`).join('')}</form>`,btn('Đóng','close-modal'));break;
    case 'notifications':modal('Thông báo','Cập nhật trong không gian làm việc — dữ liệu mẫu',`<div class="file-row">${icon('people')}<div class="file-info"><strong>Bạn được thêm vào dự án</strong><p>Nội dung tháng 11 · Quyền đóng góp</p></div></div><div class="file-row">${icon('upload')}<div class="file-info"><strong>Đã hoàn tất bản nhập mẫu</strong><p>8 hội thoại mới · 1 nội dung cần xem lại</p></div></div><div class="file-row">${icon('shield')}<div class="file-info"><strong>Không gian làm việc được quản lý</strong><p>Chủ doanh nghiệp có quyền xem dự án công việc.</p></div></div>`,btn('Đã xem','close-modal','','primary'));break;
    case 'new-project':newProject();break;
    case 'create-project':{const form=$('#new-project-form');if(!form.reportValidity())break;const pid='demo'+(++S.demoCounter);NEX.projects.unshift({id:pid,name:$('#project-name').value.trim(),description:$('#project-description').value.trim()||'Không gian công việc mới của đội ngũ.',owner:me().id,members:[],write:[],icon:'folder',color:'green',chats:0,files:0,date:'Vừa xong',tag:$('#project-category').value,cost:0});closeModal();S.projectTab='conversations';S.view='normal';go('project/'+pid);toast('Đã tạo dự án mẫu trong phiên xem. Tải lại trang để khôi phục.');break;}
    case 'share':shareProject(id);break;
    case 'share-save':{const member=$('#share-member')?.value,p=project(id);p.write=$$('[data-member-right]').filter(el=>el.value==='Đóng góp').map(el=>el.dataset.memberRight);if(member&&!p.members.includes(member))p.members.push(member);closeModal();render();toast('Đã xem trước chia sẻ trong prototype. Không thay đổi quyền thật.');break;}
    case 'quick-chat':S.draft=$('#quick-prompt')?.value||'';S.projectId=visibleProjects().find(p=>p.owner===me().id)?.id||'p1';S.newMessages.new=[];go('chat/new');break;
    case 'project-chat':S.projectId=id;S.newMessages.new=[];S.draft='';go('chat/new');break;
    case 'models':{const c=NEX.conversations.find(c=>c.id===route()[1]);S.draft=$('#chat-prompt')?.value||'';modelPicker(!!c,c?.project||S.projectId);break;}
    case 'model-select':S.provider=id;closeModal();render();break;
    case 'branch':modelPicker(true,id);break;
    case 'branch-model':S.provider=id;S.projectId=el.dataset.project;closeModal();if(!canWrite(project(S.projectId)))S.projectId=visibleProjects().find(p=>p.owner===me().id)?.id||'p1';S.newMessages.new=[];S.draft='Tiếp tục phân tích từ hội thoại trước với một góc nhìn khác.';S.view='normal';go('chat/new');toast('Nhánh mẫu mới đã mở. Chưa gửi ngữ cảnh tới nhà cung cấp.');break;
    case 'suggest':S.draft=el.dataset.text;$('#chat-prompt').value=el.dataset.text;$('#chat-prompt').focus();break;
    case 'send':{const active=NEX.conversations.find(c=>c.id===id);if(active)S.provider=active.provider;const input=$('#chat-prompt'),text=input?.value.trim();if(!text){input?.focus();toast('Nhập một câu hỏi để xem tương tác mẫu.');break;}S.newMessages[id]??=[];S.newMessages[id].push({kind:'user',text});S.draft='';S.busy=true;render();typingTimer=setTimeout(()=>{S.busy=false;S.newMessages[id].push({kind:'ai',text:'Đây là phản hồi minh họa cho prototype.\n\nVới câu hỏi của bạn, luồng thiết kế sẽ kiểm tra quyền dự án và ngân sách, gửi ngữ cảnh được chọn tới AI, rồi lưu câu trả lời vào đúng hội thoại.\n\nBạn có thể thử chọn AI khác, tạo nhánh hoặc xem các trạng thái hết ngân sách trong mục “Các màn hình”. Không có yêu cầu nào được gửi ra ngoài.'});render();$('#chat-prompt')?.focus();},900);break;}
    case 'stop':clearTimeout(typingTimer);S.busy=false;render();toast('Đã dừng mô phỏng. Câu hỏi vẫn được giữ trong phiên xem.');break;
    case 'retry':toast('Đây là phản hồi mẫu. Bạn có thể nhập câu hỏi bên dưới để xem luồng gửi và nhận.');break;
    case 'attach':modal('Chọn tài liệu cho hội thoại','Chỉ những tài liệu được chọn mới trở thành ngữ cảnh.',`${['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx','Ghi chú dự án.md'].map((f,i)=>`<label class="modal-option"><input type="checkbox" ${i<2?'checked':''}>${icon('file')}<span class="grow">${f}</span>${pill('Tệp mẫu')}</label>`).join('')}<p class="tiny muted">Prototype không đọc hoặc tải lên tệp thật.</p>`,btn('Đóng','close-modal')+btn('Dùng tài liệu mẫu','close-modal','check','primary'));break;
    case 'file-preview':filePreview(id);break;
    case 'context':contextModal(id);break;
    case 'copy-answer':toast('Đã xem thao tác sao chép. Prototype không thay đổi clipboard của bạn.');break;
    case 'like':el.setAttribute('aria-pressed','true');el.style.color='var(--green)';toast('Đã đánh dấu hữu ích trong bản mẫu.');break;
    case 'chat-options':modal('Tùy chọn hội thoại','Các thao tác thiết kế cho kho hội thoại.',`<button class="modal-option" data-action="export-chat">${icon('download')}<span class="grow">Xem trước bản xuất</span>${icon('chevron')}</button><button class="modal-option" data-action="branch" data-id="${NEX.conversations.find(c=>c.id===id)?.project||S.projectId}">${icon('branch')}<span class="grow">Tiếp tục bằng AI khác</span>${icon('chevron')}</button>`,btn('Đóng','close-modal'));break;
    case 'export-chat':modal('Xem trước bản xuất','Hội thoại được xuất trong phạm vi quyền của bạn.',`<div class="panel panel-padding"><div class="eyebrow">NEX AI HUB · HỘI THOẠI</div><h3 class="mt12">Phân tích nghiên cứu khách hàng</h3><p class="small muted mt12">Dự án: Nghiên cứu thị trường<br>Nguồn: Claude · Dữ liệu mẫu<br>Người thực hiện: Linh Nguyễn</p><div class="divider"></div><p class="small">Bản xuất bao gồm nội dung hội thoại nhận được, nguồn, thời gian và trích dẫn có trong dữ liệu.</p></div>`,btn('Đóng bản xem trước','close-modal','','primary'));break;
    case 'connect':connectModal(id||'openai');break;
    case 'provider-detail':providerDetail(id);break;
    case 'test-connection':{const selected=$('#connect-provider').value;if(selected==='meta'){providerDetail('meta');break;}modal('Kết quả kiểm tra mẫu','Đây là trạng thái minh họa, không có yêu cầu API thật.',`<div class="success-symbol">${icon('check')}</div><div style="text-align:center"><h2>Kết nối sẵn sàng</h2><p class="small muted mt12">Mẫu phản hồi cho trường hợp credential hợp lệ và model có thể sử dụng.</p></div>`,btn('Đóng','close-modal','','primary'));break;}
    case 'integration-tab':S.integrationTab=id;render();break;
    case 'subscription':{const p=provider(id);modal('Thông tin tài khoản',p.id==='openai'?'ChatGPT':p.name,`<div class="field"><label for="subscription-plan">Gói sử dụng</label><input id="subscription-plan" class="input" value="${p.account}"></div><div class="field"><label for="subscription-owner">Người quản lý</label><input id="subscription-owner" class="input" value="Minh Trần" readonly></div><div class="field"><label for="subscription-date">Ngày gia hạn mẫu</label><input id="subscription-date" class="input" type="date" value="2026-11-18"></div>${notice('Thay đổi bản ghi trong Hub không thay đổi hoặc gia hạn gói trên nền tảng AI.')}`,btn('Hủy','close-modal')+btn('Lưu bản xem trước','save-subscription','check','primary'));break;}
    case 'save-subscription':closeModal();toast('Đã xem trước thao tác lưu. Không thay đổi thuê bao thật.');break;
    case 'invite':modal('Mời nhân viên','Nhân viên chỉ cần tài khoản Nex AI Hub.',`<form id="invite-form"><div class="field"><label for="invite-name">Họ và tên</label><input class="input" id="invite-name" placeholder="Tên nhân viên mẫu" required></div><div class="field"><label for="invite-email">Email công việc</label><input class="input" id="invite-email" type="email" placeholder="nhanvien@nexmo.example" required><span class="hint">Chỉ dùng dữ liệu mẫu. Prototype không gửi email.</span></div><div class="field"><label>Vai trò</label><div class="input">Nhân viên</div></div>${notice('Nhân viên chỉ xem dự án của mình và dự án được chia sẻ. Chủ doanh nghiệp có quyền xem mọi dự án công việc.')}</form>`,btn('Hủy','close-modal')+btn('Xem trước lời mời','invite-preview','mail','primary'));break;
    case 'invite-preview':{if(!$('#invite-form').reportValidity())break;const name=$('#invite-name').value;modal('Lời mời đã sẵn sàng','Bản xem trước — chưa gửi email.',`<div class="panel panel-padding"><h3>Chào ${esc(name)},</h3><p class="small mt12">Bạn được mời tham gia NexMO Workspace để làm việc với AI và cộng tác theo dự án.</p><div class="mt24">${btn('Tham gia không gian làm việc','navigate','arrow','primary','data-path="login"')}</div></div>`,btn('Đóng','close-modal'));break;}
    case 'employee':employeeModal(id);break;
    case 'employee-save':{const input=$('#employee-budget');if(!input.reportValidity())break;person(id).limit=Number(input.value);closeModal();render();toast('Đã cập nhật hạn mức mẫu trong phiên xem, không thay đổi ngân sách thật.');break;}
    case 'lock-employee':{const locked=person(id).status==='locked';modal(locked?'Mở khóa nhân viên mẫu':'Khóa nhân viên mẫu',person(id).name,`<p class="small">${locked?'Trong sản phẩm thật, nhân viên có thể đăng nhập và dùng lại các quyền được cấp.':'Trong sản phẩm thật, nhân viên bị thu hồi phiên và không tạo được lượt AI mới. Dự án vẫn được giữ để bàn giao.'}</p>${notice('Thao tác này chỉ mô phỏng trạng thái trên bảng nhân viên.')}`,btn('Hủy','close-modal')+btn(locked?'Mở khóa mẫu':'Khóa mẫu','confirm-lock','lock',locked?'primary':'danger',`data-id="${id}"`));break;}
    case 'confirm-lock':person(id).status=person(id).status==='locked'?'active':'locked';closeModal();render();toast('Trạng thái tài khoản mẫu đã thay đổi.');break;
    case 'budget':budgetModal();break;
    case 'budget-save':{const input=$('#company-budget');if(!input.reportValidity())break;const amount=input.value;modal('Xem trước cấu hình ngân sách','Chưa áp dụng cho tài khoản hoặc dịch vụ thật.',`<div class="definition"><div class="definition-row"><span>Ngân sách công ty</span><strong>$${esc(amount)} / tháng</strong></div><div class="definition-row"><span>Cảnh báo</span><strong>80% và 95%</strong></div><div class="definition-row"><span>Khi không đủ ngân sách</span><strong>Dừng lượt AI mới</strong></div></div>${notice('Dữ liệu báo cáo mẫu vẫn giữ nguyên để bạn so sánh các màn hình. Ngân sách triển khai thật sẽ được quyết định riêng.')}`,btn('Đóng','close-modal','','primary'));break;}
    case 'month':toast('Bộ dữ liệu thiết kế đang hiển thị tháng 11/2026.');break;
    case 'export-usage':modal('Xem trước báo cáo sử dụng','Dữ liệu minh họa · Tháng 11/2026',`<div class="table-wrap"><table class="data-table compact no-wide"><thead><tr><th>Thành viên</th><th>Chi phí mẫu</th></tr></thead><tbody>${(S.role==='owner'?NEX.people:[me()]).map(p=>`<tr><td>${p.name}</td><td>${money(p.cost)}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted mt12">Sản phẩm thật sẽ xuất báo cáo theo phạm vi được phép. Prototype chỉ trình bày bản xem trước.</p>`,btn('Đóng','close-modal','','primary'));break;
    case 'import-provider':S.importProvider=id;S.importReady=false;render();break;
    case 'sample-file':S.importReady=true;render();toast('Đã chọn tệp mẫu có sẵn. Không đọc tệp trên máy.');break;
    case 'import-next':S.importStep=Math.min(3,S.importStep+1);render();window.scrollTo(0,0);break;
    case 'import-back':S.importStep=1;render();break;
    case 'import-reset':S.importStep=1;S.importReady=false;render();break;
    case 'import-help':modal('Luồng nhập hội thoại','Thiết kế nhập một chiều về Hub.',`<div class="check-list"><div>${icon('download')}Xuất dữ liệu từ tài khoản nguồn trong phạm vi được phép.</div><div>${icon('eye')}Xem trước hội thoại, tệp thiếu và bản trùng.</div><div>${icon('folder')}Chọn dự án công việc để gán dữ liệu.</div><div>${icon('check')}Kiểm tra báo cáo kết quả và nguồn gốc bản nhập.</div></div>${notice('Mức hỗ trợ phụ thuộc định dạng export thực tế. Không cam kết tự động đồng bộ mọi lịch sử.')}`,btn('Đã hiểu','close-modal','','primary'));break;
    case 'settings-tab':S.settingsTab=id;render();break;
    case 'save-settings':toast('Đã xem trước cấu hình. Không thay đổi cài đặt hệ thống thật.');break;
    case 'toggle':el.classList.toggle('on');el.setAttribute('aria-checked',String(el.classList.contains('on')));break;
    case 'audit-filter':modal('Lọc hoạt động','Thiết kế bộ lọc nhật ký.',`<div class="field"><label for="audit-actor">Người thực hiện</label><select id="audit-actor" class="input"><option>Tất cả thành viên</option>${NEX.people.map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="field"><label for="audit-action">Loại hành động</label><select id="audit-action" class="input"><option>Tất cả hành động</option><option>Xem nội dung</option><option>Thay đổi quyền</option><option>Xuất dữ liệu</option></select></div>`,btn('Đóng','close-modal')+btn('Xem bộ lọc mẫu','close-modal','filter','primary'));break;
    case 'forgot':modal('Khôi phục truy cập','Nhập email để xem trước luồng khôi phục.',`<form id="forgot-form"><div class="field"><label for="forgot-email">Email công việc</label><input id="forgot-email" class="input" type="email" value="${me().email}" required><span class="hint">Prototype không gửi email hay thay đổi mật khẩu.</span></div></form>`,btn('Quay lại','close-modal')+btn('Tiếp tục','forgot-preview','arrow','primary'));break;
    case 'forgot-preview':if(!$('#forgot-form').reportValidity())break;modal('Kiểm tra email của bạn','Trạng thái thành công minh họa.',`<div class="success-symbol">${icon('mail')}</div><p class="small">Trong sản phẩm thật, nếu địa chỉ được đăng ký, bạn sẽ nhận hướng dẫn khôi phục. Prototype không gửi email.</p>`,btn('Về đăng nhập','close-modal','','primary'));break;
    case 'login-role':S.role=id;render();break;
    case 'demo-state':S.view=id;closeModal();if(['budget','readonly'].includes(id)){S.projectId='p1';go('chat/c1');}else go('projects');render();break;
  }
  return true;
}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){go('overview');toast('Bạn đang xem giao diện mẫu. Không có xác thực thật.');}else if(e.target.id==='global-search-form'){S.librarySearch=$('#global-search').value;closeModal();go('library');}});
document.addEventListener('change',e=>{if(e.target.id==='library-provider'){S.libraryProvider=e.target.value;render();}if(e.target.id==='library-source'){S.librarySource=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='chat-prompt')S.draft=e.target.value;if(e.target.id==='quick-prompt')S.quickDraft=e.target.value;const mapping={'library-search':'librarySearch','employee-search':'employeeSearch'};const key=mapping[e.target.id];if(key){const elementId=e.target.id,pos=e.target.selectionStart;S[key]=e.target.value;render();const input=$('#'+elementId);input?.focus();input?.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dispatch('search',null,null,e);}if(e.target.id==='chat-prompt'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('[data-action="send"]')?.click();}});
